/* ============================================================
 * MultiDeviceTask
 * ============================================================ */

ThingModelJsonObj_t *CommonJson_EncodeMultiDeviceTask_AsObj(const T_MultiDeviceTask *p)
{
    ThingModelJsonObj_t *root = ThingModelJson_NewObject();
    if (!root || !p) return root;
    ThingModelJson_AddObject(root, "take_off_device_info", CommonJson_EncodeDeviceInfo_AsObj(&p->take_off_device_info));
    if (p->landing_device_infos_count > 0 && p->landing_device_infos) {
        ThingModelJsonObj_t *arr = ThingModelJson_NewArray();
        for (size_t i = 0; i < p->landing_device_infos_count; i++) {
            ThingModelJson_ArrAppendObject(arr, CommonJson_EncodeDeviceInfo_AsObj(&p->landing_device_infos[i]));
        }
        ThingModelJson_AddArray(root, "landing_device_infos", arr);
    }
    if (p->wireless_link_topo_msg.data && p->wireless_link_topo_msg.len > 0) {
        char *_hex = ThingModelHex_Encode(p->wireless_link_topo_msg.data, p->wireless_link_topo_msg.len);
        if (_hex) { ThingModelJson_AddString(root, "wireless_link_topo_msg", _hex); ThingModelMem_Free(_hex); }
    }
    return root;
}

char *CommonJson_EncodeMultiDeviceTask(const T_MultiDeviceTask *p)
{
    if (!p) return NULL;
    ThingModelJsonObj_t *root = CommonJson_EncodeMultiDeviceTask_AsObj(p);
    if (!root) return NULL;
    char *s = ThingModelJson_PrintCompact(root);
    ThingModelJson_Free(root);
    return s;
}

T_ThingModelReturnCode CommonJson_DecodeMultiDeviceTask_FromObj(const ThingModelJsonObj_t *src, T_MultiDeviceTask *out)
{
    if (!out) return THING_MODEL_RC_INVALID_ARG;
    /* out has already been zero-init'd/Free'd by the outer layer; if the caller reuses a struct with heap content, freeing it beforehand is the user's responsibility */
    if (!src) return THING_MODEL_RC_OK;
    {
        const ThingModelJsonObj_t *_o = ThingModelJson_GetItem(src, "take_off_device_info");
        if (_o) CommonJson_DecodeDeviceInfo_FromObj(_o, &out->take_off_device_info);
    }
    {
        const ThingModelJsonObj_t *_arr = ThingModelJson_GetItem(src, "landing_device_infos");
        int _n = (_arr && ThingModelJson_IsArray(_arr)) ? ThingModelJson_GetArraySize(_arr) : 0;
        if (_n > 0) {
            out->landing_device_infos = (T_DeviceInfo *)ThingModelMem_Calloc((size_t)_n, sizeof(T_DeviceInfo));
            if (out->landing_device_infos) {
                for (int i = 0; i < _n; i++)
                    CommonJson_DecodeDeviceInfo_FromObj(ThingModelJson_GetArrayItem(_arr, i), &out->landing_device_infos[i]);
                out->landing_device_infos_count = (size_t)_n;
            }
        }
    }
    {
        const char *_hex = ThingModelJson_LookupString(src, "wireless_link_topo_msg", NULL);
        if (_hex) ThingModelHex_Decode(_hex, &out->wireless_link_topo_msg.data, &out->wireless_link_topo_msg.len);
    }
    return THING_MODEL_RC_OK;
}

T_ThingModelReturnCode CommonJson_DecodeMultiDeviceTask(const char *json, T_MultiDeviceTask *out)
{
    if (!json || !out) return THING_MODEL_RC_INVALID_ARG;
    memset(out, 0, sizeof(*out));
    ThingModelJsonObj_t *r = ThingModelJson_Parse(json);
    if (!r) return THING_MODEL_RC_DECODE_ERROR;
    /* Accepts two input shapes: an outer {"data":{...}} wrapper / directly passing the data obj.
       Only drill down when the top-level "data" is an object (i.e. a genuine outer wrapper); otherwise it may be a field
       named "data" that the message itself carries (e.g. a bytes audio hex string), and drilling down by mistake would drop the whole payload. */
    const ThingModelJsonObj_t *root = r;
    {
        const ThingModelJsonObj_t *_wrap = ThingModelJson_GetItem(r, "data");
        if (_wrap && ThingModelJson_IsObject(_wrap)) root = _wrap;
    }
    T_ThingModelReturnCode rc = CommonJson_DecodeMultiDeviceTask_FromObj(root, out);
    ThingModelJson_Free(r);
    return rc;
}

void Common_FreeMultiDeviceTask(T_MultiDeviceTask *p)
{
    if (!p) return;
    Common_FreeDeviceInfo(&p->take_off_device_info);
    if (p->landing_device_infos) {
        for (size_t i = 0; i < p->landing_device_infos_count; i++) {
            Common_FreeDeviceInfo(&p->landing_device_infos[i]);
        }
        ThingModelMem_Free(p->landing_device_infos);
        p->landing_device_infos = NULL;
    }
    p->landing_device_infos_count = 0;
    ThingModelMem_Free(p->wireless_link_topo_msg.data); p->wireless_link_topo_msg.data = NULL; p->wireless_link_topo_msg.len = 0;
}

